/**
 * @method
 * @name scwin.register
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.register = async function () {
    /* sdd-asis-lifecycle:begin fn_Register — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    (document.irDataForm || { elements: [] }).action = '/list/irData.do';
    $c.util.getComponent('dma_SearchReq').set('method', 'registerIRData');
    if (await scwin.validate('document.irDataForm')) {
        if (await $c.win.confirm("등록하시겠습니까?")) {
            await scwin.tx_fn_Register();
        }
    } else {
        return;
    }
    /* sdd-asis-lifecycle:end */
};


async function chkFile(obj) {
    /* sdd-asis-lifecycle:begin fn_chkFile — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (obj.value === '') {
        return false;
    }
    const notFileType = new Array("js", "css", "html", "htm", "xml", "jsp", "asp", "php");
    const fileFullNm = obj.value;
    const fileNm = fileFullNm.substring(fileFullNm.lastIndexOf("\\") + 1);
    const fileType = fileFullNm.substring(fileFullNm.lastIndexOf(".") + 1).toLowerCase();
    for (i = 0; i < notFileType.length; i++) {
        if (notFileType[i] === fileType) {
            await $c.win.alert("선택하신 파일(" + fileNm + ")에서 " + notFileType[i] + " 파일 확장자는 사용하실 수 없습니다.");
            ($c.util.getComponent(obj.parentNode.id) && $c.util.getComponent(obj.parentNode.id).setValue) ? $c.util.getComponent(obj.parentNode.id).setValue("<input type='file' id='" + obj.id + "' name='" + obj.name + "' size='60' class='form_search' onFocus='chkFile(this);' />") : (($c.util.getComponent(obj.parentNode.id) && $c.util.getComponent(obj.parentNode.id).setText) ? $c.util.getComponent(obj.parentNode.id).setText("<input type='file' id='" + obj.id + "' name='" + obj.name + "' size='60' class='form_search' onFocus='chkFile(this);' />") : (console.warn('[sdd] 값 쓰기 미지원 컴포넌트: ' + obj.parentNode.id), void ("<input type='file' id='" + obj.id + "' name='" + obj.name + "' size='60' class='form_search' onFocus='chkFile(this);' />")));
            return false;
        }
    }
    const fileSize = 1024;
    if (fileSize / 1024 > 30720) {
        await $c.win.alert("선택하신 " + fileNm + " 파일의 최대 크기는 30M를 넘을 수 없습니다.");
        ($c.util.getComponent(obj.parentNode.id) && $c.util.getComponent(obj.parentNode.id).setValue) ? $c.util.getComponent(obj.parentNode.id).setValue("<input type='file'  id='" + obj.id + "' name='" + obj.name + "' size='60' class='form_search' onFocus='chkFile(this);' />") : (($c.util.getComponent(obj.parentNode.id) && $c.util.getComponent(obj.parentNode.id).setText) ? $c.util.getComponent(obj.parentNode.id).setText("<input type='file'  id='" + obj.id + "' name='" + obj.name + "' size='60' class='form_search' onFocus='chkFile(this);' />") : (console.warn('[sdd] 값 쓰기 미지원 컴포넌트: ' + obj.parentNode.id), void ("<input type='file'  id='" + obj.id + "' name='" + obj.name + "' size='60' class='form_search' onFocus='chkFile(this);' />")));
        return false;
    }
    $c.util.getComponent(obj.id + "Size").setValue(fileSize);
    /* sdd-asis-lifecycle:end */
}

/**
 * @method
 * @name scwin.chkFileTotalSize
 * @author Inswave
 * @date 2026. 09. 29
 * @param fileVar
 * @returns
 * @hidden N
*/
scwin.chkFileTotalSize = async function (fileVar) {
    /* sdd-asis-lifecycle:begin fn_chkFileTotalSize — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    let totalSum = 0;
    for (let i = 0; i < fileVar.length; i++) {
        const attachFileSize = $c.util.getComponent(fileVar[i]).getValue();
        if (attachFileSize !== '') {
            totalSum = totalSum + (attachFileSize);
        }
    }
    if (totalSum / 1024 > 102400) {
        await $c.win.alert("첨부파일 및 동영상의 총 파일 크기는 100M를 넘을 수 없습니다. ");
        return false;
    }
    return true;
    /* sdd-asis-lifecycle:end */
};
